__d(function(e,r,s,n,i,t,o){i.exports={questions:[{id:"k01",prof:"korane",role:"Tu es UX designer dans une start-up de livraison.",prompt:"Ton chef veut doubler les inscriptions d\u2019ici vendredi. J\u2019ai une case newsletter pr\xe9coch\xe9e qui ferait l\u2019affaire. Tu fais quoi ?",options:["Case d\xe9coch\xe9e : l\u2019accord doit \xeatre un geste volontaire","Tu pr\xe9coches, personne ne lit jamais les cases","Tu pr\xe9coches, mais en gris clair pour rester discret"],answer:0,right:"Tu ne mords pas \xe0 l\u2019hame\xe7on. Vexant.",wrong:"Rat\xe9. Une case pr\xe9coch\xe9e n\u2019est pas un consentement valable : l\u2019accord doit venir d\u2019un geste actif de la personne.",skill:"ethique"},{id:"k02",prof:"korane",role:"Tu es product designer pour une appli de streaming.",prompt:"On veut freiner les r\xe9siliations. Je propose six \xe9crans \xab Tu es s\xfbr ? \xbb avant le bouton final. G\xe9nial, non ?",options:["Six \xe9crans : ils finiront bien par abandonner","Cacher le lien de r\xe9siliation dans la page d\u2019aide","R\xe9silier aussi vite que s\u2019abonner, offre de r\xe9tention facultative"],answer:2,right:"Pas de labyrinthe pour toi. Dommage, j\u2019avais dessin\xe9 les murs.",wrong:"Perdu. Entrer facilement et sortir en rampant, c\u2019est un dark pattern. R\xe9silier doit \xeatre aussi simple que s\u2019abonner.",skill:"ethique"},{id:"k03",prof:"korane",role:"Tu es designer d\u2019une boutique de mode en ligne.",prompt:"\xab Plus que 2 articles ! \xbb sur tous les produits, m\xeame ceux qui en ont 400. \xc7a booste les ventes, para\xeet-il. Ton avis ?",options:["N\u2019afficher la raret\xe9 que lorsqu\u2019elle est r\xe9elle","Le garder partout, l\u2019urgence fait vendre","Ajouter un compte \xe0 rebours pour renforcer l\u2019effet"],answer:0,right:"Honn\xeate. C\u2019est presque reposant.",wrong:"Non. Une fausse raret\xe9 est un mensonge : les gens finissent par le voir, et la confiance part avec eux.",skill:"ethique"},{id:"k04",prof:"korane",role:"Tu es designer d\u2019un site de r\xe9servation d\u2019h\xf4tels.",prompt:"Banni\xe8re cookies : un gros bouton \xab Tout accepter \xbb et un minuscule lien gris \xab Refuser \xbb. Efficace, hein ?",options:["Garder le lien gris, refuser reste possible","Donner \xe0 \xab Refuser \xbb le m\xeame poids visuel qu\u2019\xab Accepter \xbb","Remplacer \xab Refuser \xbb par \xab Plus tard \xbb"],answer:1,right:"\xc9quilibr\xe9. Je m\u2019ennuie d\xe9j\xe0.",wrong:"Rat\xe9. Refuser doit \xeatre aussi simple qu\u2019accepter. Un choix d\xe9s\xe9quilibr\xe9 n\u2019est pas un consentement libre.",skill:"ethique"},{id:"k05",prof:"korane",role:"Tu es UX designer d\u2019un jeu mobile pour ados.",prompt:"Les notifications \xe0 23 h font exploser l\u2019engagement. Je les garde, ou ta conscience va encore me co\xfbter des chiffres ?",options:["Respecter des heures calmes et laisser r\xe9gler les alertes","Les garder, l\u2019engagement est le KPI de l\u2019\xe9quipe","Les d\xe9caler \xe0 minuit, il y a moins de concurrence"],answer:0,right:"Ta conscience co\xfbte cher. Elle a raison quand m\xeame.",wrong:"Non. Exploiter le sommeil d\u2019un public jeune, c\u2019est nuire. On mesure aussi le bien-\xeatre, pas seulement le temps pass\xe9.",skill:"ethique"},{id:"k06",prof:"korane",role:"Tu es UX designer dans une banque en ligne.",prompt:"Pas le temps d\u2019interroger des clients. Demande \xe0 tes coll\xe8gues ce qu\u2019ils en pensent, \xe7a compte pareil, non ?",options:["Faire cinq entretiens courts avec de vrais clients","Sonder les coll\xe8gues, ils utilisent aussi l\u2019appli","Se fier \xe0 son intuition de designer"],answer:0,right:"Tu insistes pour parler aux vrais gens. Quelle id\xe9e.",wrong:"Rat\xe9. Tes coll\xe8gues connaissent trop le produit : ils ne sont pas tes utilisateurs. Quelques vrais clients valent mieux.",skill:"recherche"},{id:"k07",prof:"korane",role:"Tu es UX researcher pour une appli de sport.",prompt:"En entretien, je demande : \xab Vous aimeriez une fonction de partage, non ? \xbb Tout le monde dit oui. Belle preuve, hein ?",options:["Garder la question, le oui est unanime","Poser des questions ouvertes sur ce qu\u2019ils font d\xe9j\xe0","Leur demander de noter l\u2019id\xe9e de 1 \xe0 10"],answer:1,right:"Pas de question orient\xe9e chez toi. Les miennes sont jalouses.",wrong:"Perdu. Une question ferm\xe9e souffle la r\xe9ponse. Interroge les habitudes r\xe9elles, pas des envies hypoth\xe9tiques.",skill:"recherche"},{id:"k08",prof:"korane",role:"Tu es designer d\u2019un site de covoiturage.",prompt:"Un test avec une seule personne a mal tourn\xe9. Je propose de jeter toute la refonte. Radical, \xe9l\xe9gant.",options:["Tout jeter, un \xe9chec suffit","Tester avec quelques personnes de plus avant de trancher","Ignorer ce test, il ne compte pas"],answer:1,right:"Prudent. Tu g\xe2ches mes drames.",wrong:"Non. Un seul test est un signal, pas une preuve. Avec environ cinq personnes, on rep\xe8re d\xe9j\xe0 la plupart des gros probl\xe8mes.",skill:"recherche"},{id:"k09",prof:"korane",role:"Tu es UX designer d\u2019une mutuelle sant\xe9.",prompt:"Ton persona \xab Martine, 54 ans, aime le jardinage \xbb a \xe9t\xe9 invent\xe9 en r\xe9union. Il est joli. On s\u2019en sert ?",options:["S\u2019en servir, un persona est fictif de toute fa\xe7on","B\xe2tir le persona sur des donn\xe9es de recherche","Lui ajouter une photo pour le rendre cr\xe9dible"],answer:1,right:"Tu veux des donn\xe9es. Martine est d\xe9\xe7ue.",wrong:"Rat\xe9. Un persona est fictif mais nourri de vraies recherches. Invent\xe9 en r\xe9union, il ne refl\xe8te que vos pr\xe9jug\xe9s.",skill:"recherche"},{id:"k10",prof:"korane",role:"Tu es designer dans une agence de voyages en ligne.",prompt:"Ton sondage dit que 90 % adorent la nouvelle page. Seuls les fans ont r\xe9pondu, mais bon. On f\xeate \xe7a ?",options:["F\xeater, 90 % c\u2019est indiscutable","Relancer les m\xeames fans pour confirmer","Croiser avec les donn\xe9es d\u2019usage et un panel plus large"],answer:2,right:"Pas de champagne. Bon.",wrong:"Non. Si seuls les convaincus r\xe9pondent, l\u2019\xe9chantillon est biais\xe9. Croise avec le comportement r\xe9el des gens.",skill:"recherche"},{id:"k11",prof:"korane",role:"Tu es UX designer d\u2019un site de mairie.",prompt:"Le menu a 14 rubriques. J\u2019en ajoute une 15e, \xab Divers \xbb, pour tout le reste. Pratique, non ?",options:["R\xe9organiser les rubriques gr\xe2ce \xe0 un tri par cartes","Ajouter \xab Divers \xbb, tout y rentre","R\xe9duire la taille de police du menu"],answer:0,right:"Pas de fourre-tout. Mon tiroir \xe0 c\xe2bles te salue.",wrong:"Rat\xe9. \xab Divers \xbb ne dit rien \xe0 personne. Un tri par cartes montre comment les gens regroupent vraiment les contenus.",skill:"architecture"},{id:"k12",prof:"korane",role:"Tu es designer d\u2019une appli de recettes.",prompt:"Je cache toute la navigation dans un menu hamburger, \xe7a fait \xe9pur\xe9. Le minimalisme, c\u2019est la classe.",options:["Garder les sections cl\xe9s visibles dans une barre d\u2019onglets","Tout cacher dans le hamburger, c\u2019est plus propre","Supprimer la navigation, la recherche suffit"],answer:0,right:"Visible plut\xf4t que joli. Tu me fatigues.",wrong:"Non. Ce qui est cach\xe9 est moins utilis\xe9. Sur mobile, les sections principales doivent rester sous les yeux.",skill:"architecture"},{id:"k13",prof:"korane",role:"Tu es designer d\u2019un site e-commerce de v\xe9los.",prompt:"Tes rubriques s\u2019appellent \xab Univers \xbb, \xab Inspirations \xbb, \xab Mondes \xbb. Po\xe9tique. Les gens devineront, non ?",options:["Nommer les rubriques avec les mots des utilisateurs","Garder la po\xe9sie, c\u2019est notre identit\xe9","Remplacer les mots par des ic\xf4nes"],answer:0,right:"Des libell\xe9s clairs. Quelle platitude r\xe9ussie.",wrong:"Perdu. Un libell\xe9 doit \xeatre \xe9vident, pas devin\xe9. Prends le vocabulaire de tes utilisateurs et teste-le avec eux.",skill:"architecture"},{id:"k14",prof:"korane",role:"Tu es UX designer d\u2019une appli de rendez-vous m\xe9dicaux.",prompt:"La r\xe9servation fait d\xe9j\xe0 9 \xe9crans. Je propose d\u2019en ajouter un pour la pub de nos partenaires. Rentable, non ?",options:["Ajouter l\u2019\xe9cran pub, \xe7a rapporte","Cartographier le parcours et retirer les \xe9tapes inutiles","Garder tout et ajouter une barre de progression"],answer:1,right:"Tu coupes au lieu d\u2019ajouter. Brutal. Juste.",wrong:"Non. Chaque \xe9tape inutile fait d\xe9crocher. Un user flow aide \xe0 voir ce qu\u2019on peut supprimer avant d\u2019ajouter quoi que ce soit.",skill:"architecture"},{id:"k15",prof:"korane",role:"Tu es UI designer d\u2019un tableau de bord commercial.",prompt:"Tout est important, donc je mets tout en gras, en gros et en rouge. Logique, non ?",options:["Tout en gras, comme \xe7a rien n\u2019est rat\xe9","Tout \xe0 la m\xeame taille pour rester neutre","Hi\xe9rarchiser : une info principale, le reste en retrait"],answer:2,right:"Une hi\xe9rarchie. Que tu es raisonnable.",wrong:"Rat\xe9. Si tout crie, plus rien ne ressort. La hi\xe9rarchie na\xeet du contraste entre l\u2019essentiel et le secondaire.",skill:"ui"},{id:"k16",prof:"korane",role:"Tu es UI designer pour une appli de m\xe9ditation.",prompt:"J\u2019ai trouv\xe9 cinq polices magnifiques. Je les mets toutes sur l\u2019accueil. La vari\xe9t\xe9, c\u2019est la vie.",options:["Les cinq, l\u2019\xe9cran sera plus riche","Une police diff\xe9rente pour chaque \xe9cran","Une ou deux familles, d\xe9clin\xe9es en tailles et graisses"],answer:2,right:"Sobri\xe9t\xe9. \xc7a te va bien, h\xe9las.",wrong:"Non. Trop de polices rendent l\u2019\xe9cran chaotique. Une famille bien d\xe9clin\xe9e suffit \xe0 construire la hi\xe9rarchie.",skill:"ui"},{id:"k17",prof:"korane",role:"Tu es UI designer dans une fintech.",prompt:"Les boutons \xab Payer \xbb et \xab Annuler \xbb ont exactement le m\xeame style. \xc9galit\xe9 parfaite. D\xe9mocratique, non ?",options:["M\xeame style, l\u2019utilisateur choisira","Un bouton principal marqu\xe9, l\u2019autre en secondaire","\xab Annuler \xbb plus visible, par prudence"],answer:1,right:"Un seul chef par \xe9cran. Tu as saisi.",wrong:"Perdu. L\u2019action principale doit se distinguer ; l\u2019action secondaire reste disponible, mais plus discr\xe8te.",skill:"ui"},{id:"k18",prof:"korane",role:"Tu es UI designer d\u2019un formulaire d\u2019inscription.",prompt:"Je serre tous les champs et leurs labels au maximum. L\u2019espace blanc, c\u2019est de la place perdue. Hein ?",options:["Coller chaque label \xe0 son champ, espacer les groupes","Tout serrer pour afficher plus d\u2019infos","Espacer tout de fa\xe7on identique"],answer:0,right:"Tu respires. Tes formulaires aussi.",wrong:"Rat\xe9. Loi de proximit\xe9 : ce qui est proche semble li\xe9. L\u2019espace blanc structure l\u2019\xe9cran, il n\u2019est pas perdu.",skill:"ui"},{id:"k19",prof:"korane",role:"Tu es UI designer pour le site d\u2019un mus\xe9e.",prompt:"Titre en gris clair sur fond gris un poil plus clair. \xc9l\xe9gant, discret. Le contraste, c\u2019est vulgaire, non ?",options:["Assurer un contraste suffisant, quitte \xe0 ajuster les teintes","Garder le gris sur gris, c\u2019est chic","Agrandir le titre sans toucher aux couleurs"],answer:0,right:"Lisible. Quelle vulgarit\xe9.",wrong:"Non. Sans contraste, le texte devient illisible pour beaucoup de gens. L\u2019\xe9l\xe9gance commence par la lisibilit\xe9.",skill:"ui"},{id:"k20",prof:"korane",role:"Tu es la seule designer d\u2019une mairie.",prompt:"Le site doit \xeatre accessible. Un widget \xe0 49 \u20ac par mois promet de tout r\xe9gler en une ligne de code. On signe ?",options:["Signer, le widget g\xe8re tout","Corriger le design et le code \xe0 la source","Ajouter juste un bouton \xab gros texte \xbb"],answer:1,right:"Pas de rustine magique. Je garde mon abonnement, moi.",wrong:"Rat\xe9. Un overlay ne rend pas un site accessible. Il faut corriger structure, contrastes et code, puis tester.",skill:"accessibilite"},{id:"k21",prof:"korane",role:"Tu es UX designer d\u2019un site de billetterie.",prompt:"Les erreurs du formulaire s\u2019affichent juste en rouge. Tout le monde voit le rouge, non ?",options:["Ajouter un texte explicite et une ic\xf4ne \xe0 la couleur","Garder le rouge seul, c\u2019est universel","Passer \xe0 un rouge vif qui clignote"],answer:0,right:"Couleur et texte. Tu ne laisses personne derri\xe8re. Aga\xe7ant.",wrong:"Non. Une info port\xe9e par la seule couleur \xe9chappe aux personnes daltoniennes ou malvoyantes. Ajoute du texte.",skill:"accessibilite"},{id:"k22",prof:"korane",role:"Tu es designer d\u2019une appli de courses en ligne.",prompt:"L\u2019accessibilit\xe9, on verra en V3. D\u2019abord on lance, ensuite on r\xe9pare. Malin, non ?",options:["Lancer d\u2019abord, corriger plus tard","Faire une version accessible \xe0 part","L\u2019int\xe9grer d\xe8s la conception, \xe7a co\xfbte moins cher"],answer:2,right:"D\xe8s le d\xe9but. Tu ruines mon plan de procrastination.",wrong:"Perdu. Corriger apr\xe8s co\xfbte bien plus cher, et l\u2019European Accessibility Act s\u2019applique d\xe9j\xe0 \xe0 de nombreux services.",skill:"accessibilite"},{id:"k23",prof:"korane",role:"Tu es UI designer d\u2019une appli bancaire.",prompt:"Les ic\xf4nes cliquables font 20 pixels. C\u2019est mignon. Les gros doigts, ce n\u2019est pas mon probl\xe8me.",options:["Garder 20 px, c\u2019est plus fin","Agrandir les cibles : 24 px minimum, 44 px id\xe9alement","Ajouter un zoom au double tap"],answer:1,right:"Des cibles g\xe9n\xe9reuses. Fitts et moi te saluons.",wrong:"Rat\xe9. Petite cible, clics rat\xe9s. WCAG 2.2 demande au moins 24 px ; 44 px reste plus confortable.",skill:"accessibilite"},{id:"k24",prof:"korane",role:"Tu es designer d\u2019un site d\u2019information.",prompt:"Les images n\u2019ont pas de texte alternatif. Personne ne le voit, ce truc. On zappe ?",options:["Zapper, c\u2019est invisible","Mettre le nom du fichier en alt","\xc9crire un alt utile, vide pour les images d\xe9coratives"],answer:2,right:"Tu penses aux lecteurs d\u2019\xe9cran. Rien \xe0 redire. C\u2019est rare.",wrong:"Non. Les lecteurs d\u2019\xe9cran lisent le texte alternatif. Sans lui, l\u2019image n\u2019existe pas pour une partie du public.",skill:"accessibilite"},{id:"k25",prof:"korane",role:"Tu es UX writer pour une appli de paiement.",prompt:"Message d\u2019erreur propos\xe9 : \xab Erreur 0x80042. \xbb Court, technique, myst\xe9rieux. J\u2019adore. Tu valides ?",options:["Valider, c\u2019est court","Dire ce qui s\u2019est pass\xe9 et comment corriger","\xab Oups, quelque chose s\u2019est mal pass\xe9 ! \xbb"],answer:1,right:"Clair et utile. Le myst\xe8re se meurt.",wrong:"Rat\xe9. Un bon message d\u2019erreur explique le probl\xe8me avec des mots simples et propose une solution.",skill:"ecriture"},{id:"k26",prof:"korane",role:"Tu es UX writer d\u2019une plateforme de dons.",prompt:"Refus de la popup : \xab Non merci, les enfants malades m\u2019indiff\xe8rent. \xbb \xc7a culpabilise bien. On garde ?",options:["Garder, \xe7a fait r\xe9fl\xe9chir","Pas de bouton de refus, juste une petite croix","Un refus neutre : \xab Non merci \xbb"],answer:2,right:"Pas de culpabilisation. Ma popup pleure.",wrong:"Perdu. C\u2019est du confirmshaming : humilier pour forcer le oui. Un refus doit rester neutre et respectueux.",skill:"ecriture"},{id:"k27",prof:"korane",role:"Tu es UX writer d\u2019une appli de location de voitures.",prompt:"Tous les boutons disent \xab Valider \xbb. Simple, universel. Qui a besoin de plus ?",options:["\xab Valider \xbb partout, c\u2019est coh\xe9rent","Des verbes pr\xe9cis : \xab R\xe9server la voiture \xbb, \xab Payer 89 \u20ac \xbb","\xab OK \xbb partout, c\u2019est plus court"],answer:1,right:"Des boutons qui disent ce qu\u2019ils font. Pr\xe9visible. Efficace.",wrong:"Non. Un libell\xe9 pr\xe9cis annonce ce qui arrivera au clic. \xab Valider \xbb oblige \xe0 deviner.",skill:"ecriture"},{id:"k28",prof:"korane",role:"Tu es UX writer d\u2019un site administratif.",prompt:"Ta page d\u2019aide commence par trois paragraphes de bienvenue avant l\u2019info. \xc7a pose le ton, non ?",options:["Garder, l\u2019accueil est chaleureux","Mettre l\u2019intro en gras pour qu\u2019elle soit lue","Couper l\u2019introduction et aller droit \xe0 l\u2019essentiel"],answer:2,right:"Tu coupes le blabla. Je me sens vis\xe9.",wrong:"Rat\xe9. Les gens survolent, ils ne lisent pas. Supprime les politesses et place l\u2019info utile en premier.",skill:"ecriture"},{id:"k29",prof:"korane",role:"Tu es designer dans une \xe9quipe produit de 12 personnes.",prompt:"Chacun dessine ses propres boutons. Trente variantes, c\u2019est de la cr\xe9ativit\xe9, non ?",options:["Laisser faire, la diversit\xe9 c\u2019est riche","Imposer un seul bouton, sans aucune variante","Cr\xe9er un composant bouton partag\xe9 et ses variantes"],answer:2,right:"Un composant partag\xe9. Mes trente boutons sont en deuil.",wrong:"Perdu. Trente variantes, c\u2019est de l\u2019incoh\xe9rence et de la dette. Un composant commun garde l\u2019interface coh\xe9rente.",skill:"systemes"},{id:"k30",prof:"korane",role:"Tu es UI designer dans une scale-up.",prompt:"Les devs codent la couleur #3A7BFF en dur partout. Changer de marque ? Un chercher-remplacer suffira.",options:["Chercher-remplacer, \xe7a marche tr\xe8s bien","Lister les codes couleur dans un PDF","Passer par des tokens de couleur nomm\xe9s"],answer:2,right:"Des tokens. Ton futur toi te remercie. Pas moi.",wrong:"Rat\xe9. Un token comme \xab couleur-primaire \xbb change partout d\u2019un coup. En dur, chaque modification devient une chasse.",skill:"systemes"},{id:"k31",prof:"korane",role:"Tu es designer et tu pr\xe9pares un handoff.",prompt:"Livre juste les jolis \xe9crans, sans \xe9tats d\u2019erreur ni de chargement. Les devs improviseront. \xc7a passe ?",options:["Livrer tel quel, les devs savent faire","Fournir les \xe9tats : vide, chargement, erreur, succ\xe8s","Envoyer seulement une vid\xe9o du prototype"],answer:1,right:"Tous les \xe9tats pr\xe9vus. Tu tues l\u2019improvisation.",wrong:"Non. Sans \xe9tats vides, d\u2019erreur ou de chargement, les devs inventent. Le handoff doit couvrir tous les cas.",skill:"systemes"},{id:"k32",prof:"korane",role:"Tu es designer et tu lances un design system.",prompt:"Je propose de dessiner d\u2019abord les 80 pages finales, puis d\u2019en tirer les composants. Ambitieux, non ?",options:["Dessiner les 80 pages d\u2019abord","Copier tel quel le design system d\u2019un g\xe9ant","Inventorier l\u2019existant, puis d\xe9finir les composants de base"],answer:2,right:"M\xe9thodique. Ennuyeux. Juste.",wrong:"Rat\xe9. Un inventaire de l\u2019interface r\xe9v\xe8le les doublons ; on b\xe2tit ensuite atomes, mol\xe9cules et organismes r\xe9utilisables.",skill:"systemes"},{id:"k33",prof:"korane",role:"Tu es UX designer dans une start-up RH.",prompt:"L\u2019IA m\u2019a g\xe9n\xe9r\xe9 dix personas en 30 secondes. Plus besoin d\u2019entretiens. C\u2019est \xe7a, le futur, non ?",options:["Les utiliser tels quels, c\u2019est rapide","En g\xe9n\xe9rer cent pour \xeatre plus complet","S\u2019en servir comme hypoth\xe8ses \xe0 v\xe9rifier sur le terrain"],answer:2,right:"Tu te m\xe9fies. J\u2019approuve, en silence.",wrong:"Non. L\u2019IA invente des personas plausibles, pas r\xe9els. Sans vraies donn\xe9es, tu con\xe7ois pour des fant\xf4mes.",skill:"ia"},{id:"k34",prof:"korane",role:"Tu es designer d\u2019une appli de nutrition.",prompt:"L\u2019IA a r\xe9sum\xe9 tes huit entretiens. Inutile de relire tes notes, elle ne se trompe jamais. Si ?",options:["V\xe9rifier le r\xe9sum\xe9 avec les notes et les citations","Faire confiance, c\u2019est une IA","Demander \xe0 une deuxi\xe8me IA de valider"],answer:0,right:"Tu v\xe9rifies. Les machines te craignent.",wrong:"Rat\xe9. Une IA peut oublier ou inventer des points. Relie chaque conclusion \xe0 une citation r\xe9elle.",skill:"ia"},{id:"k35",prof:"korane",role:"Tu es UX designer dans une agence.",prompt:"Pour aller vite, colle les entretiens clients, noms compris, dans un chatbot public. Efficace, non ?",options:["Coller tel quel, c\u2019est plus rapide","Anonymiser et utiliser un outil valid\xe9 par l\u2019entreprise","Ne coller que la moiti\xe9 des entretiens"],answer:1,right:"Donn\xe9es prot\xe9g\xe9es. Le RGPD t\u2019envoie des fleurs.",wrong:"Perdu. Des donn\xe9es personnelles dans un outil non valid\xe9, c\u2019est un risque RGPD. On anonymise d\u2019abord.",skill:"ia"},{id:"k36",prof:"korane",role:"Tu es UI designer junior dans un studio.",prompt:"Une IA t\u2019a g\xe9n\xe9r\xe9 une maquette compl\xe8te, elle a l\u2019air pro. Tu l\u2019envoies au client sans trop regarder ?",options:["La relire : hi\xe9rarchie, contrastes, r\xe9ponse au besoin","L\u2019envoyer, elle a l\u2019air pro","Changer juste les couleurs, puis l\u2019envoyer"],answer:0,right:"Tu relis. L\u2019IA est vex\xe9e. Moi aussi.",wrong:"Non. Une maquette g\xe9n\xe9r\xe9e peut \xeatre belle et fausse. Ton r\xf4le : juger si elle r\xe9pond au besoin et reste accessible.",skill:"ia"},{id:"a01",prof:"aniki",role:"Tu es UX researcher dans une start-up de livraison.",prompt:"Tu as interrog\xe9 six personnes. Deux th\xe8mes reviennent sans cesse. Quelle est la suite logique ?",options:["Lancer tout de suite le d\xe9veloppement d\u2019une fonction","Regrouper les observations dans un diagramme d\u2019affinit\xe9s","Refaire six entretiens identiques"],answer:1,right:"Exactement. Regrouper les notes fait \xe9merger les tendances, et l\u2019on d\xe9cide sur des faits.",wrong:"Pas tout \xe0 fait. Avant d\u2019agir, on organise les observations : le diagramme d\u2019affinit\xe9s fait appara\xeetre les th\xe8mes partag\xe9s.",skill:"recherche"},{id:"a02",prof:"aniki",role:"Tu es UX designer d\u2019une biblioth\xe8que municipale.",prompt:"Tu veux comprendre pourquoi les usagers boudent la r\xe9servation en ligne. Quelle m\xe9thode choisir en premier ?",options:["Des entretiens qualitatifs avec des usagers","Un test A/B sur la couleur du bouton","Un simple benchmark des concurrents"],answer:0,right:"Oui. Le \xab pourquoi \xbb se d\xe9couvre en \xe9coutant les gens raconter leurs pratiques.",wrong:"Pas encore. Pour comprendre un \xab pourquoi \xbb, les entretiens viennent d\u2019abord ; les tests chiffr\xe9s mesurent ensuite.",skill:"recherche"},{id:"a03",prof:"aniki",role:"Tu es designer d\u2019une appli de transports en commun.",prompt:"Tu veux comprendre tout un trajet, de la pr\xe9paration \xe0 l\u2019arriv\xe9e. Quel outil t\u2019aide le mieux ?",options:["Un guide de style","Une carte du parcours utilisateur (journey map)","Un tri par cartes"],answer:1,right:"Bien vu. La journey map montre chaque \xe9tape, les \xe9motions et les points de friction.",wrong:"Pas tout \xe0 fait. La journey map suit la personne \xe9tape par \xe9tape et r\xe9v\xe8le o\xf9 l\u2019exp\xe9rience se d\xe9grade.",skill:"recherche"},{id:"a04",prof:"aniki",role:"Tu animes un test utilisateur pour une appli bancaire.",prompt:"La participante h\xe9site longtemps sur un \xe9cran, puis te regarde. Que fais-tu ?",options:["L\u2019inviter \xe0 penser \xe0 voix haute, sans l\u2019aider","Lui montrer le bon bouton pour gagner du temps","Arr\xeater le test, l\u2019\xe9cran est rat\xe9"],answer:0,right:"Tr\xe8s bien. Ton silence bienveillant permet d\u2019observer la vraie difficult\xe9.",wrong:"Doucement. Si tu aides, tu perds l\u2019information. On l\u2019encourage \xe0 verbaliser, et on note o\xf9 elle bloque.",skill:"recherche"},{id:"a05",prof:"aniki",role:"Tu es UX designer d\u2019une plateforme de cours en ligne.",prompt:"Ton \xe9quipe doit tester une id\xe9e en cinq jours, du probl\xe8me au retour utilisateur. Quel format convient ?",options:["Un cycle de d\xe9veloppement de six mois","Un design sprint, du probl\xe8me au test du prototype","Une grande enqu\xeate annuelle"],answer:1,right:"C\u2019est cela. Le sprint permet d\u2019apprendre en une semaine, avant d\u2019investir lourdement.",wrong:"Pas ici. Le design sprint condense en cinq jours la r\xe9flexion, le prototype et le test avec de vrais utilisateurs.",skill:"recherche"},{id:"a06",prof:"aniki",role:"Tu es UX designer du site d\u2019une universit\xe9.",prompt:"Personne ne s\u2019accorde sur l\u2019organisation des rubriques. Comment trancher en partant des \xe9tudiants ?",options:["Organiser un tri par cartes avec des \xe9tudiants","Reprendre l\u2019organigramme interne","Faire voter l\u2019\xe9quipe projet"],answer:0,right:"Oui. Le tri par cartes montre comment les \xe9tudiants regroupent naturellement les contenus.",wrong:"Pas tout \xe0 fait. Les services internes ne parlent pas aux \xe9tudiants ; le tri par cartes r\xe9v\xe8le leur propre logique.",skill:"architecture"},{id:"a07",prof:"aniki",role:"Tu es designer d\u2019une appli d\u2019assurance habitation.",prompt:"Tu dois repr\xe9senter une d\xe9claration de sinistre, avec tous ses embranchements. Quel livrable choisis-tu ?",options:["Un moodboard","Un user flow","Une palette de couleurs"],answer:1,right:"Exactement. Le user flow montre chaque \xe9tape, chaque choix et chaque issue possible.",wrong:"Pas encore. Pour un parcours avec des choix, le user flow rend visibles les \xe9tapes et les embranchements.",skill:"architecture"},{id:"a08",prof:"aniki",role:"Tu es UX designer d\u2019un grand site marchand.",prompt:"Une personne arrive sur une fiche produit depuis un moteur de recherche. Comment l\u2019aider \xe0 se situer ?",options:["Lui montrer une vid\xe9o de bienvenue","La rediriger vers l\u2019accueil","Afficher un fil d\u2019Ariane et un titre de page clair"],answer:2,right:"Bien. Fil d\u2019Ariane et titre r\xe9pondent \xe0 \xab O\xf9 suis-je ? \xbb d\u2019un coup d\u2019\u0153il.",wrong:"Pas tout \xe0 fait. Chaque page doit dire o\xf9 l\u2019on se trouve : fil d\u2019Ariane et titre clair donnent ce rep\xe8re.",skill:"architecture"},{id:"a09",prof:"aniki",role:"Tu es designer d\u2019une appli de gestion de budget.",prompt:"Ton menu principal aligne onze entr\xe9es de m\xeame poids. Comment l\u2019all\xe9ger sans rien perdre ?",options:["Faire d\xe9filer les onze entr\xe9es \xe0 l\u2019horizontale","Supprimer des entr\xe9es au hasard","Regrouper par th\xe8mes et garder quatre ou cinq entr\xe9es"],answer:2,right:"Bonne approche. Moins de choix visibles, c\u2019est une d\xe9cision plus rapide : la loi de Hick.",wrong:"Pas encore. Trop d\u2019options ralentissent le choix. On regroupe et on hi\xe9rarchise pour garder l\u2019essentiel visible.",skill:"architecture"},{id:"a10",prof:"aniki",role:"Tu es UI designer d\u2019un site de presse.",prompt:"Tes articles sont denses et fatigants \xe0 lire. Quel r\xe9glage typographique aide en premier ?",options:["Justifier tout le texte","Limiter la ligne \xe0 environ 60 \xe0 75 caract\xe8res","Passer les paragraphes en majuscules"],answer:1,right:"Oui. Une ligne de longueur mod\xe9r\xe9e guide l\u2019\u0153il sans le fatiguer.",wrong:"Pas tout \xe0 fait. Des lignes trop longues \xe9puisent la lecture ; vise environ 60 \xe0 75 caract\xe8res par ligne.",skill:"ui"},{id:"a11",prof:"aniki",role:"Tu es UI designer pour une appli de sant\xe9.",prompt:"Tu choisis la couleur des alertes. Qu\u2019est-ce qui doit guider ton choix ?",options:["Ta couleur pr\xe9f\xe9r\xe9e","La tendance de l\u2019ann\xe9e","Le sens, la coh\xe9rence et un contraste suffisant"],answer:2,right:"Juste. Une couleur porte un sens, s\u2019applique partout pareil et reste lisible.",wrong:"Pas encore. La couleur porte un sens : elle doit \xeatre coh\xe9rente dans toute l\u2019appli et assez contrast\xe9e pour tous.",skill:"ui"},{id:"a12",prof:"aniki",role:"Tu es UI designer d\u2019une page de tarifs.",prompt:"Trois offres c\xf4te \xe0 c\xf4te. Tu veux qu\u2019on comprenne vite laquelle convient. Que fais-tu ?",options:["Donner \xe0 chaque offre un style tr\xe8s diff\xe9rent","Aligner les infos et faire ressortir les vraies diff\xe9rences","D\xe9crire les trois offres dans un seul paragraphe"],answer:1,right:"Bien vu. Une structure commune permet de comparer, la hi\xe9rarchie montre ce qui change.",wrong:"Pas tout \xe0 fait. Pour comparer, il faut des \xe9l\xe9ments align\xe9s et r\xe9guliers ; seules les vraies diff\xe9rences ressortent.",skill:"ui"},{id:"a13",prof:"aniki",role:"Tu es UI designer d\u2019une appli de t\xe2ches.",prompt:"Les \xe9l\xe9ments d\u2019une m\xeame carte semblent \xe9parpill\xe9s. Quel principe de la Gestalt peut t\u2019aider ?",options:["La r\xe9gion commune : un fond ou un cadre qui les r\xe9unit","La loi de Pareto","L\u2019effet de primaut\xe9"],answer:0,right:"Exactement. Un conteneur commun indique que ces \xe9l\xe9ments vont ensemble.",wrong:"Pas encore. Selon la Gestalt, des \xe9l\xe9ments plac\xe9s dans une m\xeame zone d\xe9limit\xe9e sont per\xe7us comme un groupe.",skill:"ui"},{id:"a14",prof:"aniki",role:"Tu es UI designer d\u2019un service de factures en ligne.",prompt:"Ton \xe9cran semble terne et confus. Par quoi commencer pour le clarifier ?",options:["La hi\xe9rarchie : taille, graisse et couleur du texte","Ajouter des illustrations partout","Choisir une police plus originale"],answer:0,right:"Oui. On pose d\u2019abord l\u2019ordre d\u2019importance ; la d\xe9coration vient apr\xe8s.",wrong:"Pas tout \xe0 fait. Avant de d\xe9corer, on \xe9tablit la hi\xe9rarchie : ce qui compte le plus doit se lire en premier.",skill:"ui"},{id:"a15",prof:"aniki",role:"Tu es designer au service num\xe9rique d\u2019un d\xe9partement.",prompt:"Un habitant aveugle ne parvient pas \xe0 remplir la demande en ligne. Quelle est ta premi\xe8re d\xe9marche ?",options:["Tester le formulaire avec un lecteur d\u2019\xe9cran","Lui proposer de venir au guichet","Ajouter \xab Site accessible \xbb en pied de page"],answer:0,right:"C\u2019est cela. Le lecteur d\u2019\xe9cran montre pr\xe9cis\xe9ment o\xf9 le parcours se brise.",wrong:"Pas encore. Le service en ligne doit lui \xeatre accessible ; tester au lecteur d\u2019\xe9cran r\xe9v\xe8le les obstacles \xe0 corriger.",skill:"accessibilite"},{id:"a16",prof:"aniki",role:"Tu es UX designer d\u2019un site de location.",prompt:"Ton formulaire n\u2019a que des placeholders gris, sans labels. Quel est le risque ?",options:["Aucun, c\u2019est plus \xe9pur\xe9","L\u2019indication dispara\xeet \xe0 la saisie et se lit mal","Le formulaire charge plus lentement"],answer:1,right:"Exactement. Un label visible reste l\xe0 pendant la saisie et guide aussi les lecteurs d\u2019\xe9cran.",wrong:"Pas tout \xe0 fait. Le placeholder s\u2019efface d\xe8s qu\u2019on tape et contraste peu : un label permanent est plus s\xfbr.",skill:"accessibilite"},{id:"a17",prof:"aniki",role:"Tu es designer pour un transporteur europ\xe9en.",prompt:"Ton responsable demande quel niveau d\u2019accessibilit\xe9 viser pour l\u2019appli. Que recommandes-tu ?",options:["Le niveau AA des WCAG 2.2","Le niveau A, c\u2019est suffisant","Aucun, une appli n\u2019est pas un site"],answer:0,right:"Oui. Le niveau AA est la r\xe9f\xe9rence attendue en Europe, applis mobiles comprises.",wrong:"Pas encore. La r\xe9f\xe9rence attendue est WCAG niveau AA, et l\u2019European Accessibility Act couvre aussi les applis.",skill:"accessibilite"},{id:"a18",prof:"aniki",role:"Tu es UI designer d\u2019un site de formation.",prompt:"Une utilisatrice navigue uniquement au clavier. Que doit-elle voir \xe0 chaque pression sur Tab ?",options:["Rien, le focus ab\xeeme le design","Une infobulle sur chaque \xe9l\xe9ment","Un indicateur de focus bien visible"],answer:2,right:"Bien. Le focus visible lui indique o\xf9 elle se trouve, \xe0 tout instant.",wrong:"Pas tout \xe0 fait. Sans focus visible, la navigation au clavier devient une devinette. On ne le supprime jamais.",skill:"accessibilite"},{id:"a19",prof:"aniki",role:"Tu es UX designer d\u2019une appli de tutoriels vid\xe9o.",prompt:"Comment rendre tes vid\xe9os accessibles aux personnes sourdes ou malentendantes ?",options:["Monter le volume par d\xe9faut","Ajouter une musique de fond","Des sous-titres synchronis\xe9s et une transcription"],answer:2,right:"Exactement. C\u2019est l\u2019esprit inclusif : cela sert aussi ceux qui regardent sans le son.",wrong:"Pas encore. Le contenu audio doit exister en texte : sous-titres synchronis\xe9s et transcription.",skill:"accessibilite"},{id:"a20",prof:"aniki",role:"Tu es UX writer d\u2019une appli bancaire.",prompt:"Un virement \xe9choue faute de solde suffisant. Quel message aide le mieux ?",options:["\xab Op\xe9ration refus\xe9e. \xbb","\xab Solde insuffisant : baisse le montant ou approvisionne ton compte. \xbb","\xab Erreur de transaction 403. \xbb"],answer:1,right:"Oui. Un bon message dit ce qui se passe et comment avancer.",wrong:"Pas tout \xe0 fait. Un message d\u2019erreur utile nomme le probl\xe8me simplement et propose une action concr\xe8te.",skill:"ecriture"},{id:"a21",prof:"aniki",role:"Tu es UX writer d\u2019une appli de rendez-vous m\xe9dicaux.",prompt:"L\u2019\xe9cran de confirmation affiche seulement \xab C\u2019est fait \xbb. Que manque-t-il ?",options:["Date, heure, lieu, et comment annuler","Un emoji de f\xe9licitations","Rien, c\u2019est concis"],answer:0,right:"Bien vu. Une confirmation rassure quand elle reprend l\u2019essentiel et la suite possible.",wrong:"Pas encore. Concis ne veut pas dire vague : on doit pouvoir v\xe9rifier sa r\xe9servation d\u2019un regard.",skill:"ecriture"},{id:"a22",prof:"aniki",role:"Tu es UX writer d\u2019une plateforme d\u2019emploi.",prompt:"L\u2019\xe9quipe \xe9crit tant\xf4t \xab CV \xbb, tant\xf4t \xab profil \xbb, tant\xf4t \xab dossier \xbb pour la m\xeame chose. Que proposes-tu ?",options:["Choisir un terme et le noter dans un glossaire partag\xe9","Garder la vari\xe9t\xe9 pour \xe9viter les r\xe9p\xe9titions","Laisser chaque \xe9quipe choisir"],answer:0,right:"Exactement. Un seul mot pour une seule chose, et le doute dispara\xeet.",wrong:"Pas tout \xe0 fait. En interface, varier les mots s\xe8me la confusion. Un glossaire partag\xe9 garde le vocabulaire coh\xe9rent.",skill:"ecriture"},{id:"a23",prof:"aniki",role:"Tu es UX writer d\u2019un service public en ligne.",prompt:"Ta page d\u2019aide doit \xeatre comprise par tout le monde. Quelle approche adopter ?",options:["Un vocabulaire juridique pr\xe9cis partout","Phrases courtes, mots courants, titres qui r\xe9sument","Une longue introduction rassurante"],answer:1,right:"Oui. Le langage clair profite \xe0 tous, surtout \xe0 qui lit difficilement.",wrong:"Pas encore. On survole plus qu\u2019on ne lit : phrases courtes, mots courants et titres explicites rendent l\u2019info accessible.",skill:"ecriture"},{id:"a24",prof:"aniki",role:"Tu pr\xe9sentes le futur design system \xe0 ton \xe9quipe.",prompt:"Comment expliquer simplement l\u2019organisation en atomes, mol\xe9cules et organismes ?",options:["Des \xe9l\xe9ments simples se combinent en composants plus riches","Chaque page est dessin\xe9e de fa\xe7on ind\xe9pendante","Ce sont trois niveaux de gravit\xe9 des bugs"],answer:0,right:"C\u2019est cela. Un champ et un bouton forment une recherche, qui prend place dans un en-t\xeate.",wrong:"Pas tout \xe0 fait. En Atomic Design, les atomes forment des mol\xe9cules, puis des organismes, des gabarits et des pages.",skill:"systemes"},{id:"a25",prof:"aniki",role:"Tu es UI designer d\u2019une appli multi-marques.",prompt:"Tu veux changer les couleurs selon la marque sans redessiner. Quelle base mets-tu en place ?",options:["Des maquettes dupliqu\xe9es pour chaque marque","Des captures d\u2019\xe9cran retouch\xe9es","Des tokens s\xe9mantiques, comme \xab couleur-action \xbb"],answer:2,right:"Bien. Les tokens s\xe9parent le r\xf4le de la valeur : on change la valeur, le design suit.",wrong:"Pas encore. Avec des tokens nomm\xe9s par leur r\xf4le, une marque change de couleur sans toucher aux maquettes.",skill:"systemes"},{id:"a26",prof:"aniki",role:"Tu animes un atelier avec trois d\xe9veloppeurs.",prompt:"Vous pr\xe9parez ensemble une nouvelle fonctionnalit\xe9. Comment rendre la passation des maquettes fluide ?",options:["Envoyer les fichiers la veille du sprint","Les laisser deviner les espacements","Les impliquer t\xf4t et documenter composants et \xe9tats"],answer:2,right:"Oui. Associ\xe9s t\xf4t, les devs signalent les contraintes avant qu\u2019elles ne co\xfbtent cher.",wrong:"Pas tout \xe0 fait. Un handoff r\xe9ussi repose sur une collaboration pr\xe9coce et des composants, \xe9tats et r\xe8gles document\xe9s.",skill:"systemes"},{id:"a27",prof:"aniki",role:"Tu fais vivre un design system d\xe9j\xe0 en place.",prompt:"Un coll\xe8gue a besoin d\u2019une variante de carte qui n\u2019existe pas. Quelle d\xe9marche est la plus saine ?",options:["D\xe9tacher le composant et le modifier dans son coin","Refuser toute nouvelle variante","Proposer la variante, la faire valider, la documenter"],answer:2,right:"Tr\xe8s bien. Le syst\xe8me \xe9volue avec ceux qui l\u2019utilisent, sans se fragmenter.",wrong:"Pas encore. Un composant d\xe9tach\xe9 cr\xe9e des copies divergentes. On fait \xe9voluer le syst\xe8me de fa\xe7on partag\xe9e.",skill:"systemes"},{id:"a28",prof:"aniki",role:"Tu es UX designer d\u2019une appli de fitness.",prompt:"On te demande de collecter la localisation en continu, \xab au cas o\xf9 \xbb. Comment r\xe9agis-tu ?",options:["Tout collecter, on verra plus tard","Collecter sans pr\xe9venir pour ne pas effrayer","Ne collecter que le n\xe9cessaire, avec un accord clair"],answer:2,right:"Exactement. Minimiser les donn\xe9es, c\u2019est respecter les personnes et le RGPD.",wrong:"Pas tout \xe0 fait. Le RGPD impose de ne collecter que ce qui sert un but pr\xe9cis, avec un consentement \xe9clair\xe9.",skill:"ethique"},{id:"a29",prof:"aniki",role:"Tu es designer d\u2019un comparateur d\u2019assurances.",prompt:"Un partenaire paie pour appara\xeetre en t\xeate de liste. Comment le pr\xe9senter honn\xeatement ?",options:["Le placer en t\xeate sans aucune mention","Signaler clairement le contenu sponsoris\xe9","Le pr\xe9senter comme \xab choix de la r\xe9daction \xbb"],answer:1,right:"Oui. La transparence pr\xe9serve la confiance, m\xeame quand le mod\xe8le \xe9conomique s\u2019en m\xeale.",wrong:"Pas encore. Masquer une publicit\xe9 trompe l\u2019utilisateur. Une mention \xab sponsoris\xe9 \xbb visible est le minimum honn\xeate.",skill:"ethique"},{id:"a30",prof:"aniki",role:"Tu es UX designer d\u2019un outil de reconnaissance faciale.",prompt:"En test, l\u2019outil reconna\xeet mal les peaux fonc\xe9es. Que fais-tu ?",options:["Lancer quand m\xeame, la moyenne est bonne","Retirer ces cas des r\xe9sultats","Signaler le biais et diversifier les tests"],answer:2,right:"Bien. Une bonne moyenne peut cacher une exclusion. Tu as choisi d\u2019inclure.",wrong:"Pas tout \xe0 fait. Une moyenne correcte peut masquer une exclusion grave. On rend le biais visible et on teste plus large.",skill:"ethique"},{id:"a31",prof:"aniki",role:"Tu pilotes l\u2019inclusion dans une \xe9quipe design.",prompt:"L\u2019\xe9quipe con\xe7oit pour \xab l\u2019utilisateur moyen \xbb. Quelle approche proposes-tu ?",options:["Partir des personnes exclues pour am\xe9liorer pour tous","Garder l\u2019utilisateur moyen, c\u2019est efficace","Cr\xe9er une version sp\xe9ciale \xe0 part"],answer:0,right:"Exactement. R\xe9soudre pour une personne, c\u2019est souvent \xe9tendre la solution \xe0 beaucoup d\u2019autres.",wrong:"Pas encore. L\u2019utilisateur moyen n\u2019existe pas. La conception inclusive part des exclusions pour am\xe9liorer l\u2019exp\xe9rience de tous.",skill:"ethique"},{id:"a32",prof:"aniki",role:"Tu es UX designer d\u2019un r\xe9seau social.",prompt:"Le d\xe9filement infini retient les gens, mais certains disent se sentir pi\xe9g\xe9s. Que proposes-tu ?",options:["Des points d\u2019arr\xeat et des outils de gestion du temps","Rien, le temps pass\xe9 est un bon signe","Ajouter davantage de vid\xe9os automatiques"],answer:0,right:"Bien vu. Rendre le contr\xf4le aux gens, c\u2019est respecter leur attention.",wrong:"Pas tout \xe0 fait. Temps pass\xe9 n\u2019\xe9gale pas satisfaction. Des pauses et des r\xe9glages rendent le contr\xf4le \xe0 l\u2019utilisateur.",skill:"ethique"},{id:"a33",prof:"aniki",role:"Tu es UX designer dans une agence web.",prompt:"Une IA te propose une arborescence compl\xe8te de site. Comment l\u2019utiliser avec m\xe9thode ?",options:["L\u2019adopter, elle a analys\xe9 des milliers de sites","Comme point de d\xe9part, \xe0 tester avec des utilisateurs","L\u2019ignorer, l\u2019IA ne sert \xe0 rien"],answer:1,right:"Oui. L\u2019IA acc\xe9l\xe8re l\u2019exploration, les utilisateurs confirment ce qui fonctionne.",wrong:"Pas encore. Une proposition d\u2019IA reste une hypoth\xe8se : un tri par cartes ou un test d\u2019arborescence la valide.",skill:"ia"},{id:"a34",prof:"aniki",role:"Tu es product designer d\u2019une appli avec assistant IA.",prompt:"L\u2019assistant peut se tromper. Comment le montrer honn\xeatement aux utilisateurs ?",options:["Ne rien dire pour ne pas inqui\xe9ter","Afficher \xab Fiable \xe0 100 % \xbb","Indiquer ses limites et permettre de v\xe9rifier ou corriger"],answer:2,right:"Exactement. La confiance na\xeet quand l\u2019utilisateur garde la main sur le r\xe9sultat.",wrong:"Pas tout \xe0 fait. Cacher les erreurs possibles ab\xeeme la confiance. On signale les limites et on offre un moyen de corriger.",skill:"ia"},{id:"a35",prof:"aniki",role:"Tu es UX researcher dans une mutuelle.",prompt:"Tu veux confier des verbatims clients \xe0 une IA pour les analyser. Quelle pr\xe9caution d\u2019abord ?",options:["Tout envoyer, l\u2019IA a besoin de contexte","Retirer les donn\xe9es personnelles, utiliser un outil autoris\xe9","Ne garder que les verbatims positifs"],answer:1,right:"Bien. Prot\xe9ger les personnes interrog\xe9es fait partie du m\xe9tier.",wrong:"Pas encore. Les verbatims contiennent souvent des donn\xe9es personnelles : on anonymise et on choisit un outil valid\xe9.",skill:"ia"},{id:"a36",prof:"aniki",role:"Tu es UX designer junior et tu pr\xe9pares ton portfolio.",prompt:"Une partie de ton \xe9tude de cas a \xe9t\xe9 faite avec l\u2019aide d\u2019une IA. Comment le pr\xe9senter ?",options:["Le cacher pour para\xeetre plus fort","Dire que l\u2019IA a tout fait","Expliquer ce que l\u2019IA a produit et ce que tu as d\xe9cid\xe9"],answer:2,right:"Oui. Un recruteur veut voir ton raisonnement et ta fa\xe7on de juger tes outils.",wrong:"Pas tout \xe0 fait. \xcatre transparent sur l\u2019IA montre ton esprit critique ; ce sont tes choix qui comptent.",skill:"ia"}]}},840,[]);
__d(function(e,a,n,i,t,r,o){t.exports={moves:{korane:["Crayon ac\xe9r\xe9","Regard en coin","Soupir glacial","Croquis \xe9clair","Wireframe fant\xf4me","Coup de gomme","Critique sans filtre","Taille-crayon tournoyant"],aniki:["Carnet zen","Hochement sage","Persona bouclier","Empathie profonde","It\xe9ration tranquille","Post-it apaisant","Test utilisateur","Bambou de la m\xe9thode"]},attack:{korane:["Tiens. Une maquette dans les dents.","Je n'ai m\xeame pas eu besoin de me lever.","\xc7a, c'est ce qu'on appelle un contraste AAA.","Tu l'as pas vue venir ? Comme un bouton sans affordance.","Je soupire, donc je frappe.","Petit rappel : la hi\xe9rarchie visuelle, c'est moi en haut.","Joli. J'avoue, c'\xe9tait joli."],aniki:["Avec bienveillance\u2026 mais avec fermet\xe9.","La m\xe9thode finit toujours par payer.","Respire. Et encaisse doucement.","Une bonne r\xe9ponse vaut mille arguments.","Je l'ai not\xe9 dans mon carnet : touch\xe9.","On a fait nos recherches, voil\xe0 tout."]},hurt:{korane:["A\xefe. Je ferai semblant que \xe7a ne compte pas.","Mon crayon ! Il \xe9tait taill\xe9 pile comme il faut\u2026","D'accord. Celle-l\xe0, je la note pour plus tard.","Je ne boude pas. Je r\xe9fl\xe9chis en boudant.","Hmpf. Coup de chance, \xe9videmment."],aniki:["Ouf. Bien vu, je dois le reconna\xeetre.","C'est une donn\xe9e, pas une d\xe9faite.","Je respire\u2026 et je reviens.","Belle r\xe9ponse. Je l'encaisse avec le sourire.","Mon carnet a trembl\xe9, mais il tient."]},crit:"Coup critique ! R\xe9ponse \xe9clair !",effective:"C'est super efficace !",faint:{korane:"KoRaN\xe9 s'allonge\u2026 plus que d'habitude. K.O. !",aniki:"Aniki s'assoit pour m\xe9diter sa d\xe9faite. K.O. !"},win:{korane:["Victoire. Je le savais, je ne l'ai juste pas dit.","Gagn\xe9. Tu as r\xe9pondu avec du flair. \xc7a me pla\xeet, discr\xe8tement.","Victoire nette. On en reparle pendant ma sieste."],aniki:["Victoire ! Tes r\xe9ponses \xe9taient claires et r\xe9fl\xe9chies.","Bravo. La m\xe9thode, la patience, et un peu de panache.","On a gagn\xe9 ensemble. Savoure, puis retourne apprendre."]},lose:{korane:["D\xe9faite. On a appris des choses, c'est ce qui compte. M\xeame pour moi.","Ce n'\xe9tait pas notre combat. Le prochain, on le prend.","Perdu, mais chaque erreur est un croquis pour la prochaine fois."],aniki:["D\xe9faite. Une d\xe9faite montre ce qu'il faut revoir : c'est une carte, pas un verdict.","Tu t'es bien battu. On r\xe9vise un peu, et on revient plus fort.","Ce n'est qu'un combat. Ta progression, elle, continue."]}}},841,[]);